void main() { final now = DateTime.now(); print(now); final istNow = now.toUtc().add(const Duration(hours: 5, minutes: 30)); print(istNow); final marketStartTodayIST = DateTime.utc(istNow.year, istNow.month, istNow.day, 9, 15); print(marketStartTodayIST); final marketStartTodayLocal = marketStartTodayIST.subtract(const Duration(hours: 5, minutes: 30)).toLocal(); print(marketStartTodayLocal); DateTime generationEnd = DateTime.fromMillisecondsSinceEpoch((now.millisecondsSinceEpoch ~/ (5 * 60 * 1000)) * (5 * 60 * 1000), isUtc: now.isUtc); print(generationEnd); }
